echo 'from rich.text import Text
from rich.style import Style

def test_expand_tabs_style():
    # Create text: "abc" (red), "\t" (blue), "def" (red)
    text = Text("abc", style=Style(color="red"))
    text.append("\t", style=Style(color="blue"))
    text.append("def", style=Style(color="red"))

    text.expand_tabs(tab_size=8)

    # "abc" is 3 chars. Tab expands to 5 spaces.
    # Indices 3, 4, 5, 6, 7 should be blue.
    # Index 8, 9, 10 should be red.

    def get_style_at(text, offset):
        style = text.style
        for start, end, s in text._spans:
            if start <= offset < end:
                style = s
        return style

    all_blue = True
    for i in range(3, 8):
        if get_style_at(text, i) != Style(color="blue"):
            print(f"Index {i} is not blue: {get_style_at(text, i)}")
            all_blue = False

    if not all_blue:
        print("FAILED: Expanded spaces are not blue!")
    else:
        print("SUCCESS: Expanded spaces are blue!")

if __name__ == "__main__":
    test_expand_tabs_style()' > /tmp/repro.py
